public void completed(WorkflowEventArgs _args)
{
    WorkflowContext context = _args.parmWorkflowContext();

    next completed(_args);

    if(context.parmTableId () == tableNum(PurchTable))
    {
        PurchTable purchTable = PurchTable::findRecId(context.parmRecId());

        if(purchTable.RecId != 0 && purchTable.DocumentState == VersioningDocumentState::Approved)
        {
            try
            {
                METPurchTableConfirmationService::postConfirmation(purchTable.PurchId);
            }
            catch (Exception::Error)
            {
                error(strFmt("METPurchaseOrderConfirmQueueErr", purchTable.PurchId));
                // Do not throw error if update fails, as the workflow is already completed and we don't want to block that.
            }

        }
    }
}
